    const n = big ? 100000 : r.int(1, 12);
    const nums = big ? r.arr(n, -10000, 10000) : r.arr(n, -4, 4);
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    const f = [...cnt.values()].sort((a, b) => b - a);
    const ok = []; // k values where the answer is unique
    for (let k = 1; k <= f.length; k++) if (k === f.length || f[k - 1] > f[k]) ok.push(k);
    return [nums, r.pick(ok)];
  }

