function mostFrequent(nums: number[], k: number): number[] {
  const count = new Map<number, number>();
  for (const x of nums) count.set(x, (count.get(x) ?? 0) + 1);
  return [...count.keys()]
    .sort((a, b) => count.get(b)! - count.get(a)!)
    .slice(0, k);
}

